import Foundation

/// Decides what must never (or only briefly) be kept.
public enum SecretDetector {
    /// Pasteboard markers set by password managers and other well-behaved apps
    /// (see nspasteboard.org). If any is present the copy is ignored entirely.
    public static let ignoredPasteboardTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        // Legacy markers still used by some apps.
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    /// Copies made while one of these apps is frontmost are ignored.
    public static let defaultIgnoredApps: [String] = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "org.keepassxc.keepassxc",
    ]

    public static func shouldIgnore(pasteboardTypes: [String]) -> Bool {
        pasteboardTypes.contains(where: ignoredPasteboardTypes.contains)
    }

    private static let tokenPrefixes = [
        "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-",
        "sk-", "sk_live_", "rk_live_", "xoxb-", "xoxp-", "xapp-", "AKIA", "AIza",
    ]

    /// Heuristic for passwords, API tokens and private keys copied from places
    /// that don't mark the pasteboard as concealed.
    public static func looksLikeSecret(_ text: String) -> Bool {
        let s = text.trimmingCharacters(in: .whitespacesAndNewlines)

        if s.hasPrefix("-----BEGIN"), s.contains("PRIVATE KEY") { return true }

        let hasWhitespace = s.contains(where: \.isWhitespace)
        if !hasWhitespace, s.count >= 20, tokenPrefixes.contains(where: s.hasPrefix) { return true }
        if !hasWhitespace, s.hasPrefix("eyJ"), s.split(separator: ".").count == 3, s.count >= 30 {
            return true // JWT
        }

        guard (8...128).contains(s.count), !hasWhitespace, s.allSatisfy(\.isASCII) else { return false }
        if s.contains("://") || s.hasPrefix("/") || s.hasPrefix("~") { return false }

        var lower = false, upper = false, digit = false, symbol = false
        var transitions = 0
        var previousClass = -1
        for ch in s {
            let cls: Int
            if ch.isLowercase { lower = true; cls = 0 }
            else if ch.isUppercase { upper = true; cls = 1 }
            else if ch.isNumber { digit = true; cls = 2 }
            else { symbol = true; cls = 3 }
            if previousClass != -1, cls != previousClass { transitions += 1 }
            previousClass = cls
        }
        let classes = [lower, upper, digit, symbol].filter { $0 }.count
        // Random strings switch character class far more often than words,
        // identifiers (processPayment2) or product names (MacBookPro2024).
        let switchRate = Double(transitions) / Double(s.count - 1)

        if symbol {
            return classes >= 3 && switchRate >= 0.4
        }
        return s.count >= 12 && classes == 3 && switchRate >= 0.5
    }
}
